"   useEffect(() => {
     if (isInventoryModalOpen || isAlertsModalOpen) {
       fetch(`${API_BASE}/api/inventory/raw`, {
         headers: {
           'Authorization': `Bearer ${localStorage.getItem('pos_token')}`
         }
       })
       .then(res => res.json())
       .then(data => {
         if (Array.isArray(data)) {
           setInventoryItems(data);
         }
       })
       .catch(err => console.error("Failed to fetch inventory:", err));
     }
   }, [isInventoryModalOpen, isAlertsModalOpen]);"

